CREATE TABLE user_roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), role_id UUID NOT NULL REFERENCES roles(id), project_id UUID REFERENCES projects(id), state_id UUID REFERENCES states(id), created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX user_roles_scope_unique ON user_roles(user_id,role_id,COALESCE(project_id,'00000000-0000-0000-0000-000000000000'),COALESCE(state_id,'00000000-0000-0000-0000-000000000000')); CREATE INDEX user_roles_user_idx ON user_roles(user_id); CREATE INDEX user_roles_project_idx ON user_roles(project_id);
